const baseline=JSON.parse(fs.readFileSync(path.join(root,'as-is','evidence.json'),'utf8'));
const digest=s=>crypto.createHash('sha256').update(s).digest('hex');
const baselineHash=digest(fs.readFileSync(path.join(root,'as-is','evidence.json')));
const models=structuredClone(baseline.objectRegistry);
