function add(n,internal,display,type,req,def,editing,life,extras={}){
 const o=obj(n);if(o.fields.some(f=>f.internalName===internal))throw Error('Duplicate '+n+'.'+internal);
 const f={evidenceId:null,recordId:null,packageItemId:null,internalName:internal,displayName:display,declaredOn:n,classification:'Proposed',disposition:'Add',proposalId:`PF-${String(++seq).padStart(3,'0')}`,typeContract:type,required:req,defaultContract:def,editContract:editing,lifecycleContract:life,relationshipTarget:null,cardinality:null,inverse:null,...extras};o.fields.push(f);return f;
}
function newObject(n,display,authority='Inspections-owned proposed governed catalogue'){
 const o={internalName:n,displayName:display,recordId:null,packageItemId:null,evidenceId:null,inheritanceParent:'None',scope:'Proposed',disposition:'Add',designClassification:'Proposed',authority,metadata:{IsAbstract:false,IsSystem:false,IsLocalizable:true},fields:[],seedRecords:[]};models.push(o);byName.set(n,o);return o;
}
function scalar(n,i,label,type,req,def,editability,life){return add(n,i,label,type,req,def,editability,life);}
