let contract='# Inspections target — Field-level contract\n\nCompanion to the [Target Solution Specification](solution-specification.md). Baseline is preserved separately. Proposed changes are not implemented. Exact existing metadata and partial dependencies remain traceable to [baseline evidence](../as-is/evidence.json). Null/omitted precision, timezone, population or physical binding is labelled Unresolved, not guessed. A modified row is the current target; the original remains only in baseline evidence.\n\n## 1. Object inventory\n\nEvery entry has one numbered subsection below. Existing objects retain stable GUIDs. Proposed external interfaces have no assigned technical GUID and must be bound to the enterprise authority. No relationship target is an inheritance parent. Partial external fields do not purport to reconstruct the complete owning application.\n';
contract+=table(['Internal name / display name','Stable object ID / evidence','Inheritance parent','Disposition / authority','Direct field rows'],models.map(o=>[`${o.internalName} / ${o.displayName}`,o.recordId?`${o.recordId}; ${o.evidenceId}`:'Proposed — GUID unassigned',typeof o.inheritanceParent==='object'?o.inheritanceParent.name:o.inheritanceParent,`${o.disposition}; ${o.authority}`,o.fields.length]));
contract+='\n## 2. Canonical field tables\n\nReq is Y, N or Conditional. Conditional means the named stage/mode/rule in that row, enforced on the server; incomplete drafts can save where explicitly permitted. Exact display names occupy the Field column; internal names/IDs are in lifecycle cells. Scope references and automation IDs refer to the main specification.\n\nShared inherited conditions are specified on the declaring base with the concrete consumer explicitly named; fields are not redeclared on descendants. Published fields are read only, with temporary native generation helpers isolated as exceptions. Native framework/base filters and security remain effective unless an explicit target row supersedes them. Retained undocumented restrictions stay unresolved under P-10.\n';
for(const [i,o]of models.entries()){
 contract+=`\n### 2.${i+1} ${o.displayName}\n\n**Internal name:** ${code(o.internalName)}. **Inheritance parent:** ${typeof o.inheritanceParent==='object'?code(o.inheritanceParent.name):o.inheritanceParent}.\n\n**Directly declared fields:** ${o.fields.length?o.fields.map(f=>code(f.internalName)).join(', '):'None exported; inherited fields remain on their inheritance base'}.\n\n**Classification / authority:** ${o.designClassification}; ${o.authority}. **Disposition:** ${o.disposition}.\n`;
 if(o.recordId)contract+=`\n**Baseline identity:** ${o.recordId}; ${o.evidenceId}; ${o.path}.\n`;
 if(typeof o.inheritanceParent==='object')contract+='\nInherited declarations are defined once in the referenced inheritance-base subsection. Subtype-specific restrictions in shared rows apply to this concrete consumer; there is no duplicate storage.\n';
 if(o.internalName==='Shared_OperationalResource')contract+='\n**Unresolved external interface:** Field names and constraints describe consumer requirements, not verified physical master-data metadata. Binding must preserve the agreed authority; no local implementation is authorized by the diagram alone.\n';
 if(o.fields.length)contract+=table(headers,o.fields.map(f=>[f.displayName,f.typeContract,f.required,f.defaultContract,f.editContract,`${f.lifecycleContract} [${f.classification}; ${f.disposition}]. ${f.evidence||f.proposalId}; internal ${f.internalName}.`]));
 if(o.seedRecords.length){const keys=[...new Set(o.seedRecords.flatMap(r=>Object.keys(r.values)))];contract+='\nInitial values:\n\n'+(o.scope==='Proposed'||o.seedRecords.some(r=>r.classification.startsWith('Proposed'))?'Proposed seed/upsert records; no existing record GUID is invented. Inherited columns represent values rather than duplicate declarations.':'Extracted exported values; not proof of all tenant data.')+'\n';contract+=table(['Classification',...keys],o.seedRecords.map(r=>[r.classification,...keys.map(k=>r.values[k]??'NULL')]));}
}
contract+='\n## 3. Publication reconciliation\n\nThe following mappings were extracted from E265/E2348. They are baseline evidence; target controls and new semantic copies refine them as specified below.\n';
contract+=table(['Handler','Destination','Extracted source'],copyMappings.map(m=>[m.handler,m.destination,m.source]));
contract+='\n### 3.1 Target publication dispositions\n';
contract+=table(['Declaring object','Field','Current target publication rule'],models.filter(o=>['CLF_QuestObject','CLF_ChecklistObject','CLF_QuestAbstractObject','CLF_CheckliAbstractObject','CLF_PubQuestObject','CLF_PubChecklistObject'].includes(o.internalName)).flatMap(o=>o.fields.map(f=>[o.internalName,f.internalName,f.publication||f.lifecycleContract])));
contract+='\nEvery inherited business field in Question Abstract and Checklist Abstract is copied to the corresponding inherited value on the published instance unless specifically identified as runtime/system metadata. Runtime DateCreated is native publication time; DateModifiedHel is a system-derived helper rather than an author-editable value. New ContributesToOutcome, NegativeChoices, NegativeBoolean and ActionRequiredIfNegative fields follow the same author-to-published mapping. BranchConfirmed and ResponseOutcome belong only to operational answers and are not publication fields.\n\nTemporary hCheckAnswer runtime helper writes in the native answer-generation mechanism are a deliberate compatibility exception to immutable question content. Serialize generation per issued inspection, clear helpers after use and prove isolation under P-03; do not use this exception to edit wording, response semantics or memberships.\n\n## 4. Contract completeness and implementation limits\n\nAll documented fields have one canonical row; all inventory objects have a numbered section. That is documentation coverage, not proof that every target mechanism is executable. Missing baseline lengths/precision, read-only population, physical external bindings, native callback/transaction behavior and new expression syntax remain Unresolved under the main specification gates. The implementation contract cannot be marked fully validated until those gates close.\n';
fs.writeFileSync(path.join(out,'field-contract.md'),contract);
