let auto='# Inspections target — Existing automation reconciliation\n\nCompanion to [the target specification](solution-specification.md). Each exported handler is accounted for once below. A Retain disposition does not prove runtime behavior. Exact old flows stay in the baseline; changed target responsibilities are defined here and in AH-01 through AH-07/WF-01. IsEnabled and numeric ActionType are independent of descriptive names. Shared handlers must be scoped, not globally disabled where other applications use them.\n';
auto+=table(['Evidence / stable ID','Declaring object','Handler / exported enabled / ActionType','Current target disposition'],baseline.items.filter(x=>x.item.ObjectName==='MetObjectActionEntity').map(x=>{const own=baseline.relations.find(r=>r.start===x.evidenceId&&r.source==='Object');const o=sourceItems.get(own?.end);const d=x.item.FieldData;return [`${x.evidenceId}; ${x.item.RecordId}`,o?.FieldData?.Name||'Unresolved',`${d.Name}; enabled=${d.IsEnabled}; ActionType=${d.ActionType}`,handlerPlans[x.evidenceId]||'Retain shared handler and existing unrelated application behavior; no target extension or new dependency.'];}));
auto+='\n## Workflow reconciliation\n\nInspection retains existing schema and four stage/action identities; ordered target logic replaces flows described in §6.2. Inspection Action Plan retains schema identity but removes deferred inspection-release gating and moves notes validation before completion. Audit/multiple-checklist/Sub-checklist drafts remain installed compatibility configuration; pending draft changes are not adopted as current Inspection runtime.\n';
auto+=table(['Workflow schema / evidence','Stable record ID','Target disposition'],baseline.items.filter(x=>x.item.ObjectName==='SysWorkflowDraftSchemaEntity').map(x=>[`${x.item.FieldData.Name}; ${x.evidenceId}`,x.item.RecordId,['Inspection','Inspection Action Plan'].includes(x.item.FieldData.Name)?'Modify as target §6/7; preserve identity; publish/test controlled replacement':'Retain installed compatibility schema and original active/pending flags; no target user pathway']));
auto+='\n## Form, validation and notification reconciliation\n\nFor Inspections-specific forms, replace conditional behavior that uses live TypeOfInspec settings with applied snapshot values; remove numeric score/Findings UI and automatic role creation controls; apply server-equivalent source/equipment/requiredness rules. Retain unrelated shared views/profiles. Role/catalogue expressions use stable codes after migration. Inspect all baseline 121 views/65 profiles for references before publishing the changed application; the source register preserves every definition.\n\nExisting notification templates are retained as content assets; invocation changes follow §6/7. No release-change assignment event remains active alongside task-entry assignment. Completion content identifies inspection acceptance separately from action closure. Native requiredness/uniqueness validators remain unless a specifically scoped rule is replaced; use pretransition validation for all new conditions.\n';
fs.writeFileSync(path.join(out,'automation-reconciliation.md'),auto);
let diagrams='# Inspections target — Complete logical model\n\n[Main specification](solution-specification.md) contains the active-path overview. These partitions include every retained framework/dependency object and proposed object, with direct inheritance only. Display labels map stable Mermaid identifiers to exact display names. Compatibility-only objects remain installed but do not authorize new Inspections Findings or audit pathways. Cardinalities are logical export interpretations or explicitly proposed field contracts. New catalogue selectors have inverse disabled. Inverse-only exported navigation is labelled instead of inventing its missing declaring field. External interfaces have unresolved physical bindings.\n';
const sid=o=>o.internalName.replace(/[^A-Za-z0-9_]/g,'_');
const moduleFor=o=>o.scope==='Proposed'?(o.internalName.startsWith('Shared_')?'Shared interface':'Proposed catalogues'):(baseline.relations.find(r=>r.start===o.evidenceId&&r.source==='Module')?.end||'Shared dependencies');
